class Bad:
    n: int

def check(x: int) -> int fail Bad:
    """Return x if it is even, otherwise fail with Bad(n=x)."""
    ex check(2) == Ok(2)
    ex check(3) == Err(Bad(n=3))
    if x % 2 == 1:
        fail Bad(n=x)
    return x

def all_even(xs: list[int]) -> list[int] fail Bad:
    """Check every element of xs in parallel. Return xs unchanged if all are even,
    otherwise fail with the Bad of the lowest-index odd element, regardless of
    which thread finishes first."""
    post out.len() == xs.len()
    ex all_even([2, 4, 6]) == Ok([2, 4, 6])
    ex all_even([]) == Ok([])
    ex all_even([2, 3, 5]) == Err(Bad(n=3))
    ex all_even([5, 4, 3]) == Err(Bad(n=5))
    rs = par [check(x) else -1 for x in xs]
    for i in range(xs.len()):
        if rs[i] == -1:
            fail Bad(n=xs[i])
    return xs.copy()

